def transform(a):
    o=[row[:] for row in a]
    # clear left panel rows 1..6 cols 1..7? remove pattern all nonzero at c0..8? demos output all zeros there
    for r in range(8):
        for c in range(9): o[r][c]=0
    # shift right board inner cells (rows 1..5, cols 10..18) up one
    for r in range(1,6):
        for c in range(10,19): o[r][c]=a[r+1][c]
    # copy 5 mask from left panel coordinates to right shifted +10
    for r in range(8):
        for c in range(9):
            if a[r][c]==5 and 11<=c+10<=17:
                o[r][c+10]=5
    return o
